<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Profile\Infrastructure\Driver\Html\Panels;

use Civi\Lughauth\Features\OAuth\Profile\Domain\MfaSetup;

class MfaPanel
{
    public function render(
        bool $enabled,
        string $saveUrl,
        string $cancelUrl,
        ?MfaSetup $setup = null,
        ?string $error = null,
        bool $success = false,
        array $t = [],
    ): string {
        $saveUrl = htmlspecialchars($saveUrl);
        $cancelUrl = htmlspecialchars($cancelUrl);

        $errorHtml = $error !== null && $error !== ''
            ? '<p class="error">' . htmlspecialchars($error) . '</p>'
            : '';
        $successHtml = $success
            ? '<p class="change-password-success">' . htmlspecialchars($t['success']) . '</p>'
            : '';

        if ($enabled) {
            return <<<HTML
                <h1>{$t['title']}</h1>
                {$successHtml}
                {$errorHtml}
                <p>{$t['enabledHelp']}</p>
                <form method="POST" action="{$saveUrl}" class="change-password-form">
                    <input type="hidden" name="action" value="disable" />
                    <div class="profile-actions">
                        <input class="primary-button" type="submit" value="{$t['disable']}" />
                        <a class="secondary-button" href="{$cancelUrl}">{$t['backToProfile']}</a>
                    </div>
                </form>
                HTML;
        }

        $seed = htmlspecialchars($setup?->seed ?? '');
        $qrImage = $setup?->qrImage ?? null;
        $qrBlock = '';
        if ($qrImage !== null && $qrImage !== '') {
            $qrEscaped = htmlspecialchars($qrImage);
            $qrBlock = '<p><img src="' . $qrEscaped . '" alt="MFA QR" style="max-width:220px;height:auto;" /></p>';
        }

        return <<<HTML
            <h1>{$t['title']}</h1>
            {$successHtml}
            {$errorHtml}
            <p>{$t['help']}</p>
            {$qrBlock}
            <form method="POST" action="{$saveUrl}" class="change-password-form">
                <input type="hidden" name="action" value="enable" />
                <input type="hidden" name="seed" value="{$seed}" />
                <label>{$t['secret']}
                    <input type="text" value="{$seed}" readonly />
                </label>
                <label>{$t['otp']}
                    <input type="text" name="otp" required />
                </label>
                <div class="profile-actions">
                    <input class="primary-button" type="submit" value="{$t['enable']}" />
                    <a class="secondary-button" href="{$cancelUrl}">{$t['cancel']}</a>
                </div>
            </form>
            HTML;
    }
}
